        buffer.put((byte)0);  // extra null to mark end of list

        // Reset position
        buffer.position(0);

        // Simulate the getStringList loop
        int offset = 0;

        // First string: read until null
        while (buffer.get() != 0) {
            // just advancing position
        }

        int limit = buffer.position() - 1;
        String result1 = MemoryUtil.memUTF8(buffer, limit - offset, offset);
        offset = buffer.position();

        // Second string: read until null
        while (buffer.get() != 0) {
            // just advancing position
        }

        limit = buffer.position() - 1;
        String result2 = MemoryUtil.memUTF8(buffer, limit - offset, offset);

        System.out.println("Result 1: " + result1);
        System.out.println("Result 2: " + result2);

        if (str1.equals(result1) && str2.equals(result2)) {
            System.out.println("TEST PASSED!");
        } else {
            System.out.println("TEST FAILED!");
            System.out.println("Expected: [" + str1 + ", " + str2 + "]");
            System.out.println("Got: [" + result1 + ", " + result2 + "]");
        }
    }
}
